def calc(expr):
    class Parser:
        def __init__(self, expr):
            self.expr = expr
            self.pos = 0

        def peek(self):
            while self.pos < len(self.expr) and self.expr[self.pos] == ' ':
                self.pos += 1
            if self.pos < len(self.expr):
                return self.expr[self.pos]
            return None

        def consume(self):
            self.pos += 1

        def parse_number(self):
            while self.pos < len(self.expr) and self.expr[self.pos] == ' ':
                self.pos += 1
            num = 0
            while self.pos < len(self.expr) and self.expr[self.pos].isdigit():
                num = num * 10 + int(self.expr[self.pos])
                self.pos += 1
            return num

        def parse_unary(self):
            while self.pos < len(self.expr) and self.expr[self.pos] == ' ':
                self.pos += 1

            negate = False
            while self.pos < len(self.expr) and self.expr[self.pos] == '-':
                negate = not negate
                self.pos += 1
                while self.pos < len(self.expr) and self.expr[self.pos] == ' ':
                    self.pos += 1

            if self.peek() == '(':
                self.pos += 1
                result = self.parse_addition()
                while self.pos < len(self.expr) and self.expr[self.pos] == ' ':
                    self.pos += 1
                self.pos += 1  # consume ')'
            else:
                result = self.parse_number()

            if negate:
                result = -result
            return result

        def parse_multiplication(self):
            result = self.parse_unary()

            while True:
                while self.pos < len(self.expr) and self.expr[self.pos] == ' ':
                    self.pos += 1

                if self.pos < len(self.expr) and self.expr[self.pos] in '*/':
                    op = self.expr[self.pos]
                    self.pos += 1
                    right = self.parse_unary()
                    if op == '*':
                        result = result * right
                    else:
                        # Integer division truncating toward zero
                        if (result < 0) != (right < 0) and result % right != 0:
                            result = result // right + 1
                        else:
                            result = result // right
                else:
                    break

            return result

        def parse_addition(self):
            result = self.parse_multiplication()

            while True:
                while self.pos < len(self.expr) and self.expr[self.pos] == ' ':
                    self.pos += 1

                if self.pos < len(self.expr) and self.expr[self.pos] in '+-':
                    op = self.expr[self.pos]
                    self.pos += 1
                    right = self.parse_multiplication()
                    if op == '+':
                        result = result + right
                    else:
                        result = result - right
                else:
                    break

            return result

    parser = Parser(expr)
    return parser.parse_addition()

